import os
import stat


def audit_file_permissions(directory: str) -> list[dict]:
    findings = []

    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)

            try:
                st = os.lstat(path)
            except OSError:
                continue

            if not stat.S_ISREG(st.st_mode):
                continue

            mode = stat.S_IMODE(st.st_mode)
            issues = []

            if mode & stat.S_IWOTH:
                issues.append("world-writable")
            if mode & stat.S_IXOTH:
                issues.append("world-executable")

            if issues:
                findings.append({
                    "path": path,
                    "mode": oct(mode),
                    "issues": issues,
                })

    return findings
